/*
 * A035877  Number of points of l_1 norm n in the "diamond" lattice D^+_2, i.
 *          e. the rectangular lattice generated by vectors (1, 1) and (-1/2,
 *          1/2).
 * https://oeis.org/A035877
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(0) = 1; for n > 0, a(2n) = 12n, a(2n+1) = 4n + 2
 * Range:     u8 n <= 43, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)1;

    if ((n & 1ULL) == 0) {
        seq_t half = (seq_t)(n >> 1);        /* n/2 */
        return (seq_t)12 * half;
    } else {
        seq_t half = (seq_t)(n >> 1);        /* (n-1)/2 */
        return (seq_t)4 * half + (seq_t)2;
    }
}
